import{_ as o,o as t,c as s,a2 as e}from"./chunks/framework.A5mep7Fe.js";const L=JSON.parse('{"title":"🔁 04 · MLOps 与 LLMOps","description":"","frontmatter":{},"headers":[],"relativePath":"08-AI应用开发/04-MLOps与LLMOps.md","filePath":"08-AI应用开发/04-MLOps与LLMOps.md","lastUpdated":1786806808000}'),l={name:"08-AI应用开发/04-MLOps与LLMOps.md"};function r(i,a,p,n,c,d){return t(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="🔁-04-·-mlops-与-llmops" tabindex="-1">🔁 04 · MLOps 与 LLMOps <a class="header-anchor" href="#🔁-04-·-mlops-与-llmops" aria-label="Permalink to &quot;🔁 04 · MLOps 与 LLMOps&quot;">​</a></h1><blockquote><p>让 AI 系统「可迭代、可回滚、可监控」的工程体系。没有它，每次改模型都是盲飞。</p></blockquote><hr><h2 id="一、mlops-传统-ml-生命周期" tabindex="-1">一、MLOps（传统 ML 生命周期） <a class="header-anchor" href="#一、mlops-传统-ml-生命周期" aria-label="Permalink to &quot;一、MLOps（传统 ML 生命周期）&quot;">​</a></h2><ul><li><strong>数据</strong>：版本管理（Data Version Control）、质量监控、漂移检测</li><li><strong>训练</strong>：实验追踪（MLflow）、可复现、超参管理</li><li><strong>部署</strong>：模型注册、AB、金丝雀、回滚</li><li><strong>监控</strong>：预测质量、数据漂移、性能</li></ul><h2 id="二、llmops-大模型特化" tabindex="-1">二、LLMOps（大模型特化） <a class="header-anchor" href="#二、llmops-大模型特化" aria-label="Permalink to &quot;二、LLMOps（大模型特化）&quot;">​</a></h2><p>相比 MLOps 新增：</p><ul><li><strong>Prompt 版本管理</strong>：Prompt 即代码，需版本化、灰度、回滚</li><li><strong>模型注册与路由</strong>：多模型/多版本管理、流量切分</li><li><strong>评测闭环</strong>：固化评测集 + 自动打分（RAGAS/LLM-as-Judge），改必测</li><li><strong>成本可观测</strong>：token 计量、调用分布、异常高成本告警</li><li><strong>推理服务运维</strong>：GPU 调度、KV Cache、连续批处理（见 <code>07-运维</code>）</li></ul><h2 id="三、ci-cd-for-ai" tabindex="-1">三、CI/CD for AI <a class="header-anchor" href="#三、ci-cd-for-ai" aria-label="Permalink to &quot;三、CI/CD for AI&quot;">​</a></h2><ul><li>代码 CI + 数据校验 + 评测回归 + 自动部署</li><li>Prompt/模型变更走评审 + 灰度 + 监控</li></ul><h2 id="四、数据闭环-持续提升" tabindex="-1">四、数据闭环（持续提升） <a class="header-anchor" href="#四、数据闭环-持续提升" aria-label="Permalink to &quot;四、数据闭环（持续提升）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户反馈/线上结果 → 收集难例 → 标注/合成 → 微调/知识库更新 → 评测 → 发布</span></span></code></pre></div><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：LLMOps 比 MLOps 多了什么？</strong></p><blockquote><p>Prompt 版本管理、模型路由与灰度、评测闭环（LLM-as-Judge）、成本可观测、推理服务（GPU/KV Cache）运维。模型本身往往不重训，重 Prompt/知识库迭代。</p></blockquote><p><strong>Q2：怎么保证每次改 Prompt 不退化？</strong></p><blockquote><p>维护评测集 + 自动化评测门禁，指标未达标阻断发布；Prompt 版本化可一键回滚；灰度小流量验证再全量。</p></blockquote><hr><p>➡️ 下一步：<a href="./05-商业化落地">05-商业化落地</a></p>',19)])])}const u=o(l,[["render",r]]);export{L as __pageData,u as default};
